"""Generate js/levels-sql.js: 8 chapters, one new idea per quest, EN/ES/DE."""
import json, sys
sys.path.insert(0, __import__('os').path.dirname(__file__))
from answers import A

# Each quest: key, options, example, and per language [idea, lesson, task, hint].
CH = []

def chapter(cid, tables, title, story, quests, **kw):
    CH.append(dict(id=cid, tables=tables, text={l: {'title': title[l], 'story': story[l]} for l in title}, quests=quests, **kw))

def q(key, ex, en, es, de, **opts):
    d = dict(answer=A[key], example=ex, text={'en': dict(zip(['idea', 'lesson', 'task', 'hint'], en)),
                                              'es': dict(zip(['idea', 'lesson', 'task', 'hint'], es)),
                                              'de': dict(zip(['idea', 'lesson', 'task', 'hint'], de))})
    d.update(opts)
    return d

