# ---------------------------------------------------------------- 8
chapter('sq8', ['mobs', 'hunts', 'players'],
 {'en': 'Bonus: Leaderboards', 'es': 'Extra: clasificaciones', 'de': 'Bonus: Bestenlisten'},
 {'en': 'Bonus chapter ⭐ — tools that real analysts love. <b>Window functions</b> calculate across rows <i>without</i> squashing them into groups: ranks, running totals, the best in each group.',
  'es': 'Capítulo extra ⭐ — herramientas que encantan a los analistas. Las <b>funciones de ventana</b> calculan entre filas <i>sin</i> juntarlas en grupos: puestos, totales acumulados, el mejor de cada grupo.',
  'de': 'Bonuskapitel ⭐ — Werkzeuge, die echte Analysten lieben. <b>Fensterfunktionen</b> rechnen über Zeilen hinweg, <i>ohne</i> sie zu Gruppen zusammenzuquetschen: Ränge, laufende Summen, die Besten jeder Gruppe.'},
 [
 q('8.1', 'SELECT name, damage,\n  RANK() OVER (ORDER BY damage DESC) AS place\nFROM mobs',
   ['RANK() OVER', '<code>RANK() OVER (ORDER BY … DESC)</code> gives every row its place: 1, 2, 3… Rows that tie get the same place.', 'Rank all mobs by <b>health</b>, highest first. Show <b>name</b>, <b>health</b> and the <b>rank</b>.', 'RANK() OVER (ORDER BY health DESC)'],
   ['RANK() OVER', '<code>RANK() OVER (ORDER BY … DESC)</code> le da a cada fila su puesto: 1, 2, 3… Las filas empatadas reciben el mismo puesto.', 'Clasifica todas las criaturas por <b>health</b>, de mayor a menor. Muestra <b>name</b>, <b>health</b> y el <b>puesto</b>.', 'RANK() OVER (ORDER BY health DESC)'],
   ['RANK() OVER', '<code>RANK() OVER (ORDER BY … DESC)</code> gibt jeder Zeile ihren Platz: 1, 2, 3… Gleichstände bekommen denselben Platz.', 'Ordne alle Mobs nach <b>health</b>, das höchste zuerst. Zeig <b>name</b>, <b>health</b> und den <b>Rang</b>.', 'RANK() OVER (ORDER BY health DESC)'],
   freeNames=True),
 q('8.2', 'SELECT name, home, health,\n  RANK() OVER (PARTITION BY home ORDER BY health DESC)\nFROM mobs',
   ['PARTITION BY', '<code>PARTITION BY type</code> restarts the ranking for every type — a "rank inside each group".', 'Rank the mobs by <b>damage</b> <b>inside each type</b>. Show <b>name</b>, <b>type</b>, <b>damage</b> and the rank.', 'RANK() OVER (PARTITION BY type ORDER BY damage DESC)'],
   ['PARTITION BY', '<code>PARTITION BY type</code> reinicia la clasificación para cada tipo — un "puesto dentro de cada grupo".', 'Clasifica las criaturas por <b>damage</b> <b>dentro de cada type</b>. Muestra <b>name</b>, <b>type</b>, <b>damage</b> y el puesto.', 'RANK() OVER (PARTITION BY type ORDER BY damage DESC)'],
   ['PARTITION BY', '<code>PARTITION BY type</code> fängt die Rangliste für jeden Typ neu an — ein "Rang innerhalb jeder Gruppe".', 'Ordne die Mobs nach <b>damage</b> <b>innerhalb jedes type</b>. Zeig <b>name</b>, <b>type</b>, <b>damage</b> und den Rang.', 'RANK() OVER (PARTITION BY type ORDER BY damage DESC)'],
   freeNames=True),
 q('8.3', 'WITH d AS (SELECT day, COUNT(*) AS n FROM hunts GROUP BY day)\nSELECT day, n, SUM(n) OVER (ORDER BY day) FROM d',
   ['Running total', '<code>SUM(x) OVER (ORDER BY day)</code> adds up everything <b>so far</b> — a running total. Tip: first make daily totals with <code>WITH</code>, then run the window over them.', 'Show each <b>day</b>, the <b>XP earned that day</b>, and the <b>running total</b> of XP up to that day.', 'WITH d AS (SELECT day, SUM(xp) AS xp FROM hunts GROUP BY day) SELECT day, xp, SUM(xp) OVER (ORDER BY day) FROM d'],
   ['Total acumulado', '<code>SUM(x) OVER (ORDER BY day)</code> suma todo lo que va <b>hasta ahora</b> — un total acumulado. Consejo: primero calcula los totales por día con <code>WITH</code> y luego aplica la ventana.', 'Muestra cada <b>day</b>, la <b>XP ganada ese día</b> y el <b>total acumulado</b> de XP hasta ese día.', 'WITH d AS (SELECT day, SUM(xp) AS xp FROM hunts GROUP BY day) SELECT day, xp, SUM(xp) OVER (ORDER BY day) FROM d'],
   ['Laufende Summe', '<code>SUM(x) OVER (ORDER BY day)</code> zählt alles <b>bis jetzt</b> zusammen — eine laufende Summe. Tipp: Rechne zuerst mit <code>WITH</code> die Tagessummen aus und lass dann das Fenster darüber laufen.', 'Zeig jeden <b>day</b>, die <b>XP dieses Tages</b> und die <b>laufende Summe</b> der XP bis zu diesem Tag.', 'WITH d AS (SELECT day, SUM(xp) AS xp FROM hunts GROUP BY day) SELECT day, xp, SUM(xp) OVER (ORDER BY day) FROM d'],
   freeNames=True),
 q('8.4', None,
   ['Final leaderboard', 'Put it all together: JOIN, GROUP BY, WITH and RANK — this is exactly how real game leaderboards are built.', 'Build the final leaderboard: each <b>player name</b>, their <b>total XP</b>, and their <b>rank</b>.', 'WITH t AS (… player name + SUM(xp) …) SELECT name, total, RANK() OVER (ORDER BY total DESC) FROM t'],
   ['Clasificación final', 'Júntalo todo: JOIN, GROUP BY, WITH y RANK — así se construyen las clasificaciones de los juegos de verdad.', 'Construye la clasificación final: el <b>nombre de cada jugador</b>, su <b>XP total</b> y su <b>puesto</b>.', 'WITH t AS (… nombre + SUM(xp) …) SELECT name, total, RANK() OVER (ORDER BY total DESC) FROM t'],
   ['Die finale Bestenliste', 'Alles zusammen: JOIN, GROUP BY, WITH und RANK — genau so werden echte Spiel-Bestenlisten gebaut.', 'Bau die finale Bestenliste: jeder <b>Spielername</b>, seine <b>gesamte XP</b> und sein <b>Rang</b>.', 'WITH t AS (… Spielername + SUM(xp) …) SELECT name, total, RANK() OVER (ORDER BY total DESC) FROM t'],
   freeNames=True),
 ], bonus=True)

out = sys.argv[1]
with open(out, 'w') as f:
    f.write('// Generated by gen_levels.py — SQL chapters. One new idea per quest.\n(function () {\n')
    f.write('  window.SQL_LEVELS = ' + json.dumps(CH, ensure_ascii=False, indent=1) + ';\n})();\n')
n = sum(len(c['quests']) for c in CH)
print('wrote', out, len(CH), 'chapters,', n, 'quests')
for c in CH:
    for i, qq in enumerate(c['quests']):
        for l in ('en', 'es', 'de'):
            assert all(qq['text'][l].get(k) for k in ('idea', 'lesson', 'task', 'hint')), (c['id'], i, l)
print('all quests have idea/lesson/task/hint in 3 languages')
